from taf.ul.kpi_selector.operations.bts_cold_startup.classical_bts_cold_startup.bts_cold_startup_prototype import \
    BtsColdStartup
from taf.ul.kpi_selector.operations.factory_prototype.classical_factory_prototype import OperationFactoryPrototype


class BtsColdStartupFactory(OperationFactoryPrototype):
    def __init__(self):
        super(BtsColdStartupFactory, self).__init__()

    def get_kpi(self):
        """
        Gets kpi for BTS cold start-up operation.
        :return: dictionary with timeout, requirement and operation description for BTS cold start-up
        :rtype: dict
        """
        return BtsColdStartup(self.bts).get_kpi()
